<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/shop-error.php';

/** Decode and re-encode uploads; filenames and output paths are generated by the server. */
function admin_store_menu_photo(array $upload): string
{
    if (($upload['error'] ?? null) === UPLOAD_ERR_INI_SIZE || ($upload['error'] ?? null) === UPLOAD_ERR_FORM_SIZE) throw new ShopError(413, 'Choose a photo smaller than 6 MB.');
    if (($upload['error'] ?? null) !== UPLOAD_ERR_OK || !is_string($upload['tmp_name'] ?? null) || !is_uploaded_file($upload['tmp_name'])) throw new ShopError(422, 'The photo could not be uploaded. Choose it again and retry.');
    if (!is_int($upload['size'] ?? null) || $upload['size'] < 1 || $upload['size'] > 6 * 1024 * 1024) throw new ShopError(413, 'Choose a photo smaller than 6 MB.');
    if (!extension_loaded('gd') || !extension_loaded('fileinfo')) throw new ShopError(503, 'Photo uploads need the PHP GD and Fileinfo extensions enabled.');
    $file = $upload['tmp_name'];
    $info = @getimagesize($file);
    $types = [IMAGETYPE_JPEG => 'image/jpeg', IMAGETYPE_PNG => 'image/png', IMAGETYPE_WEBP => 'image/webp'];
    if (!$info || !isset($types[$info[2]]) || (new finfo(FILEINFO_MIME_TYPE))->file($file) !== $types[$info[2]]) throw new ShopError(422, 'Choose a valid JPG, PNG or WebP photo.');
    if ($info[0] < 64 || $info[1] < 64 || $info[0] > 8000 || $info[1] > 8000 || $info[0] * $info[1] > 16000000) throw new ShopError(422, 'Use a photo at least 64 × 64 pixels and no larger than 16 megapixels.');
    $source = match ($info[2]) {
        IMAGETYPE_JPEG => @imagecreatefromjpeg($file),
        IMAGETYPE_PNG => @imagecreatefrompng($file),
        IMAGETYPE_WEBP => @imagecreatefromwebp($file),
    };
    if (!$source) throw new ShopError(422, 'This photo could not be read. Try another JPG, PNG or WebP file.');
    $canvas = null;
    try {
        $orientation = $info[2] === IMAGETYPE_JPEG && function_exists('exif_read_data') ? (int) ((@exif_read_data($file)['Orientation'] ?? 1)) : 1;
        $angle = match ($orientation) { 3 => 180, 5, 6 => -90, 7, 8 => 90, default => 0 };
        if ($angle) { $rotated = imagerotate($source, $angle, 0); if (!$rotated) throw new ShopError(422, 'This photo could not be rotated. Try another file.'); imagedestroy($source); $source = $rotated; }
        if (in_array($orientation, [2, 5, 7], true)) imageflip($source, IMG_FLIP_HORIZONTAL);
        if ($orientation === 4) imageflip($source, IMG_FLIP_VERTICAL);
        $ratio = min(1, 1600 / max(imagesx($source), imagesy($source)));
        $width = max(1, (int) round(imagesx($source) * $ratio)); $height = max(1, (int) round(imagesy($source) * $ratio));
        $canvas = imagecreatetruecolor($width, $height);
        imagefill($canvas, 0, 0, imagecolorallocate($canvas, 19, 17, 14));
        imagecopyresampled($canvas, $source, 0, 0, 0, 0, $width, $height, imagesx($source), imagesy($source));
        imageinterlace($canvas, true);
        $relative = 'assets/img/uploads/menu-' . bin2hex(random_bytes(16)) . '.jpg';
        $directory = dirname(__DIR__, 2) . '/assets/img/uploads';
        if (!is_dir($directory) || !is_writable($directory)) throw new ShopError(503, 'The menu photo folder is not writable. Check the server folder permissions.');
        if (!imagejpeg($canvas, dirname(__DIR__, 2) . '/' . $relative, 88)) { @unlink(dirname(__DIR__, 2) . '/' . $relative); throw new ShopError(503, 'The photo could not be saved. Please try again.'); }
        return $relative;
    } finally {
        imagedestroy($source);
        if ($canvas) imagedestroy($canvas);
    }
}

/** Commit the new asset and menu row together; an unsuccessful save removes only its new file. */
function admin_save_menu_with_photo(PDO $pdo, array $data, array $upload): array
{
    $photo = admin_store_menu_photo($upload);
    try {
        $pdo->beginTransaction();
        $data['image'] = $photo;
        $item = catalogue_save($pdo, $data);
        $pdo->commit();
        return $item;
    } catch (Throwable $error) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        if (preg_match('#^assets/img/uploads/menu-[a-f0-9]{32}\.jpg$#D', $photo)) @unlink(dirname(__DIR__, 2) . '/' . $photo);
        throw $error;
    }
}
